commit ae8d32b4b24af09efc80794ba6e68c64093dde73
Author: Jonas Wagner <jbw@google.com>
Date:   Wed May 2 17:29:29 2018 +0200

    Fix buffer-overread when checking for task lists.

    The direct cause of the bug is that Hoedown does not check size
    correctly when it tries to parse a loose task list. This leads to
    problems when parsing tasks inside definition lists, where the
    assumption that content is wrapped in <p> tags does not always hold.

    We fix both the direct cause of the bug and add a check to ensure that
    we do not aim to parse tasks in definition lists.

    This bug was detected by the Google Autofuzz project.
---
 src/html.c | 33 ++++++++++++++++++---------------
 1 file changed, 18 insertions(+), 15 deletions(-)

diff --git a/src/html.c b/src/html.c
index 37b15ca..bac089c 100644
--- a/src/html.c
+++ b/src/html.c
@@ -498,6 +498,7 @@ rndr_listitem(hoedown_buffer *ob, const hoedown_buffer *content, const hoedown_b
                hoedown_html_renderer_state *state = data->opaque;
                size_t prefix = 0;
                size_t size = content->size;
+               int is_li_tag = 0;
                while (size && content->data[size - 1] == '\n')
                        size--;

@@ -507,6 +508,7 @@ rndr_listitem(hoedown_buffer *ob, const hoedown_buffer *content, const hoedown_b
                        HOEDOWN_BUFPUTSL(ob, "<dt");
                } else {
                        HOEDOWN_BUFPUTSL(ob, "<li");
+                       is_li_tag = 1;
                }

                if (attr && attr->size) {
@@ -514,24 +516,25 @@ rndr_listitem(hoedown_buffer *ob, const hoedown_buffer *content, const hoedown_b
                }
                hoedown_buffer_putc(ob, '>');

-               if (USE_TASK_LIST(state) && size >= 3) {
+               if (USE_TASK_LIST(state) && is_li_tag && size >= 3) {
+                       /* Block list items are wrapped in <p> tags. Output the opening tag now,
+                        * then check for a task list. */
                        if (*flags & HOEDOWN_LI_BLOCK) {
                                prefix = 3;
-                       }
-                       if (strncmp((char *)content->data + prefix, "[ ]", 3) == 0) {
-                               hoedown_buffer_put(ob, content->data, prefix);
-                               HOEDOWN_BUFPUTSL(ob, "<input type=\"checkbox\"");
-                               hoedown_buffer_puts(ob, USE_XHTML(state) ? "/>" : ">");
-                               prefix += 3;
-                               *flags |= HOEDOWN_LI_TASK;
-                       } else if (strncasecmp((char *)content->data + prefix, "[x]", 3) == 0) {
                                hoedown_buffer_put(ob, content->data, prefix);
-                               HOEDOWN_BUFPUTSL(ob, "<input checked=\"\" type=\"checkbox\"");
-                               hoedown_buffer_puts(ob, USE_XHTML(state) ? "/>" : ">");
-                               prefix += 3;
-                               *flags |= HOEDOWN_LI_TASK;
-                       } else {
-                               prefix = 0;
+                       }
+                       if (size >= prefix + 3) {
+                               if (strncmp((char *)content->data + prefix, "[ ]", 3) == 0) {
+                                       HOEDOWN_BUFPUTSL(ob, "<input type=\"checkbox\"");
+                                       hoedown_buffer_puts(ob, USE_XHTML(state) ? "/>" : ">");
+                                       prefix += 3;
+                                       *flags |= HOEDOWN_LI_TASK;
+                               } else if (strncasecmp((char *)content->data + prefix, "[x]", 3) == 0) {
+                                       HOEDOWN_BUFPUTSL(ob, "<input checked=\"\" type=\"checkbox\"");
+                                       hoedown_buffer_puts(ob, USE_XHTML(state) ? "/>" : ">");
+                                       prefix += 3;
+                                       *flags |= HOEDOWN_LI_TASK;
+                               }
                        }
                }

